pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address; the property: when DrugDealer() is invoked by the configured CEO, initialized becomes true
    function testFuzz_property(address caller) public {
        // keep domain wide but non-zero
        vm.assume(caller != address(0));

        // The reference contract's ceoAddress is hardcoded to 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26
        // We fuzz a caller and only proceed when caller equals that CEO so the fuzzer can find that input
        address ceo = 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26;

        // fund the caller so that if the function ever required value it would be ok (not needed here, but safe)
        vm.deal(caller, 1 ether);

        bool ok;
        if (caller == ceo) {
            vm.prank(caller);
            // call DrugDealer() and capture whether it succeeds
            try c.DrugDealer() {
                ok = true;
            } catch {
                ok = false;
            }
            // After a successful call by the CEO, the reference contract sets initialized = true.
            // The property we assert: initialized is true whenever the CEO caller's DrugDealer() call succeeded.
            // This holds for the reference for all inputs; the mutant (which sets initialized=false in seedMarket)
            // will still allow DrugDealer() to succeed but leave initialized false for some scenarios (the fuzzer will find the CEO input).
            if (ok) {
                assertTrue(c.initialized());
            } else {
                // if call reverted (shouldn't for correct contract), still assert that initialized is false (consistent observation)
                assertTrue(!c.initialized());
            }
        } else {
            // When caller is not the CEO, DrugDealer() reverts; ensure that behavior holds by observing the call result
            vm.prank(caller);
            try c.DrugDealer() {
                // If it unexpectedly succeeds, we still check initialized is true
                assertTrue(c.initialized());
            } catch {
                // expected revert, assert initialized remains its default (false)
                assertTrue(!c.initialized());
            }
        }
    }
}

