    function testFuzz_property(address caller) public {
        // Keep domain wide but avoid the zero address which isn't meaningful for EOA tests
        vm.assume(caller != address(0));

        // Fund the caller so any payable behavior would be permitted
        vm.deal(caller, 1 ether);

        // Try calling DrugDealer() as the fuzzed caller. We capture whether it succeeded.
        bool ok;
