contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Try to distinguish P (sets initialized=true in seedMarket) from M (doesn't set initialized).
    // Call sequence: seedMarket(drugs) then getFreeKilo() from this contract's externally-visible behavior.
    // We require this contract to hold enough balance to call seedMarket if msg.value is used by seedMarket (it is payable),
    // so caller must fund InvMutTest before invoking run.

    function run(uint256 drugs) public {
        // Preconditions: marketDrugs must be 0 so seedMarket will accept the call.
        // We read it first and require it's zero to make the test focused.
        require(c.marketDrugs() == 0);

        // Call seedMarket with given drugs. This is the single state-changing setup call needed.
        // seedMarket is payable; send no value (allowed). If target uses msg.value, caller could send value by
        // making this contract hold ETH and using call with value — but problem statement forbids reading msg.value here.
        c.seedMarket(drugs);

        // After seedMarket on the original contract P, initialized == true and getFreeKilo can be called when Kilos[this]==0.
        // We ensure Kilos[this] is 0 by reading it.
        require(c.getMyKilo() == 0);

        // Call getFreeKilo which will revert if initialized==false or Kilos[this] != 0.
        // The distinguishing property: on P this will succeed and set Kilos>0; on M it will revert.
        c.getFreeKilo();

        // Read kilos after the call.
        uint256 kilosAfter = c.getMyKilo();

        // Assert that kilosAfter is at least the declared STARTING_KILOS (a public variable).
        // This is a general rule: seedMarket enables claiming the free starting kilos.
        assert(kilosAfter >= c.STARTING_KILOS());
    }

    // Allow the contract to receive Ether if test setup wants to fund it.
    receive() external payable {}
}

